import sys
input = sys.stdin.readline

def main():
    MAXA = 10000001

    # Compute smallest prime factor for all numbers up to MAXA-1
    spf = list(range(MAXA))
    for i in range(2, int(MAXA**0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i*i, MAXA, i):
                if spf[j] == j:
                    spf[j] = i

    # Compute pi(n) = number of primes <= n
    pi = [0] * MAXA
    cnt = 0
    for i in range(MAXA):
        if i >= 2 and spf[i] == i:
            cnt += 1
        pi[i] = cnt

    t = int(input())
    out = []
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        xor_val = 0
        for x in a:
            if x % 2 == 0:
                continue  # g(x) = 0
            elif x == 1:
                xor_val ^= 1
            else:
                xor_val ^= pi[spf[x]]
        out.append("Alice" if xor_val != 0 else "Bob")
    sys.stdout.write("\n".join(out) + "\n")

main()
